-- Iniciar transacción
BEGIN TRANSACTION

BEGIN TRY

IF EXISTS(SELECT * FROM TownshipDistrictByBillingSV WITH(NOLOCK))
BEGIN
	PRINT ('DATOS YA EXISTE');
	RETURN
END
ELSE
BEGIN
	PRINT ('SE INSERTARAN DATOS')
	
	
END

	COMMIT TRANSACTION
	print 'Inserción exitosa'

END TRY
BEGIN CATCH
	-- Revertir transacción en caso de error
	IF @@TRANCOUNT > 0
		ROLLBACK TRANSACTION
    
	-- Capturar información del error
	SELECT ERROR_MESSAGE(),
			ERROR_SEVERITY(),
			ERROR_STATE()

END CATCH